return items.map(item => {
  const resposta = item.json.output || "";

  let respostaHTML = resposta;

  // 1️⃣ Remover "### " do início das linhas (títulos em Markdown)
  respostaHTML = respostaHTML.replace(/^###\s?/gm, "");

  // 2️⃣ Converter **texto** em <strong>texto</strong>
  respostaHTML = respostaHTML.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

  // 3️⃣ [NOVO] Converter links [texto](url) para <a>, mas APENAS se a URL for do "unoerpwiki"

  // Regex para encontrar o padrão [texto](url)
  const linkRegex = /\[(.*?)\]\((.*?)\)/g;

  // Usamos uma função como segundo argumento do 'replace'
  respostaHTML = respostaHTML.replace(linkRegex, (match, texto, url) => {
    // match: A string inteira, ex: "[UNO ERP Wiki](https://unoerp...)"
    // texto: O 1º grupo de captura, ex: "UNO ERP Wiki"
    // url:   O 2º grupo de captura, ex: "https://unoerpwiki.herokuapp.com/..."

    // ⬇️ Esta é a sua lógica de filtro!
    if (url.includes('unoerpwiki.herokuapp.com')) {
      // Se a URL contém o prefixo, converte para HTML
      // Adicionei target="_blank" para abrir o link em uma nova aba
      return `<a href="${url}" target="_blank">${texto}</a>`;
    } else {
      // Se não for a URL desejada, retorna o texto original sem formatar
      return match;
    }
  });

  // 4️⃣ Converter quebras de linha em <br> (Mantido no final)
  respostaHTML = respostaHTML.replace(/\n/g, "<br>");

  return {
    json: {
      resposta: respostaHTML
    }
  };
});
